WITH flattened AS (SELECT id, host, log_ts, level, status_code, key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS key, attr_value) SELECT id, host, level, key, attr_value, CUME_DIST() OVER (PARTITION BY level ORDER BY status_code ASC) AS status_code_cume_dist, ROUND(status_code / SUM(status_code) OVER (PARTITION BY level, key), 4) AS status_code_share, ROUND(status_code / SUM(status_code) OVER (PARTITION BY level), 4) AS status_code_share_2, RANK() OVER (ORDER BY status_code DESC) AS status_code_rank, AVG(status_code) OVER (PARTITION BY host, key ORDER BY CAST(log_ts AS BIGINT) ASC RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) AS status_code_avg_30m FROM flattened
